def live_group_members(pgid):
    members = []
    for entry in Path('/proc').iterdir():
        if entry.name.isdigit():
            try:
                info = process_identity(int(entry.name))
            except (PermissionError, ProcessLookupError):
                continue
            if info and info['pgid'] == pgid and info['state'] != 'Z':
                members.append(info)
    return members

